/**
 * CloudLink descriptor — a typed handle to a configured CloudLink on the
 * Elementum platform. CloudLinks aren't authored by the EDK (they hold
 * credentials and stay manually configured); this ref exists so EDK
 * builders that need to point at one can do so type-safely instead of
 * accepting a raw id string.
 *
 * Mirrors the `AiProviderConnector` pattern in `./ai-provider.ts`.
 *
 * ```ts
 *   // connectors/cloud-links.ts
 *   export const prodSnowflake = cloudLink({
 *     id: "ab100edd-b301-4a16-b269-e5347449ad9b",
 *     name: "Prod Snowflake",
 *   });
 *
 *   // search-tables/linked-tickets.ts
 *   import { prodSnowflake } from "../connectors/cloud-links.js";
 *
 *   searchTable({
 *     kind: "linked",
 *     cloudLink: prodSnowflake,
 *     // ...
 *   });
 * ```
 */
export function cloudLink(opts) {
    return {
        id: opts.id,
        ...(opts.name != null && { name: opts.name }),
    };
}
